// Standalone probe: replicate the kernel's QK^T path (swizzle, ldmatrix, mma)
// and dump S for one block vs a CPU reference.
#include <cstdio>
#include <cstdint>
#include <cuda_bf16.h>
#include <math.h>
using bf16 = __nv_bfloat16;
constexpr int BLOCK_M = 64, BLOCK_N = 64, HEAD_DIM = 128, NUM_WARPS = 8, NUM_THREADS = 256;

__device__ __forceinline__ uint32_t smem_swz16(const void* base, int row, int col8) {
    int sw = col8 ^ (row & 7);
    return (uint32_t)__cvta_generic_to_shared((const char*)base + row * 256 + sw * 16);
}
__device__ __forceinline__ void ldmatrix_x4(uint32_t r[4], const void* base, int r0, int c0) {
    const int lane = threadIdx.x & 31;
    const int trow = r0 + (lane & 7) + ((lane >> 4) << 3);
    const int tcol8 = (c0 >> 3) + ((lane >> 3) & 1);
    asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
                 : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3])
                 : "r"(smem_swz16(base, trow, tcol8)));
}
__device__ __forceinline__ void ldmatrix_x2_k(uint32_t r[2], const void* base, int r0, int c0) {
    const int lane = threadIdx.x & 31;
    const int trow = r0 + (lane & 7);
    const int tcol8 = (c0 >> 3) + (lane >> 3);
    asm volatile("ldmatrix.sync.aligned.m8n8.x2.shared.b16 {%0,%1}, [%2];\n"
                 : "=r"(r[0]), "=r"(r[1])
                 : "r"(smem_swz16(base, trow, tcol8)));
}
__device__ __forceinline__ void mma_m16n8k16_bf16(
