__global__ void qk_kernel(const bf16* q, const bf16* k, float* S_out, int seq_len, float scale) {
    __shared__ bf16 sQ[BLOCK_M][HEAD_DIM];
    __shared__ bf16 sK[BLOCK_M][HEAD_DIM];
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int wrow = (warp / 2) * 16;
    const long long qbase = 0, kvbase = 0;
    for (int i = threadIdx.x; i < BLOCK_M * HEAD_DIM; i += NUM_THREADS) {
        const int r = i >> 7, c = i & 127;
        const int gr = r;
        bf16 val = (gr < seq_len) ? q[qbase + (long long)gr * HEAD_DIM + c] : __float2bfloat16(0.f);
        const int sw = (c >> 3) ^ (r & 7);
        sQ[r][sw * 8 + (c & 7)] = val;
    }
    for (int i = threadIdx.x; i < BLOCK_M * HEAD_DIM; i += NUM_THREADS) {
        const int r = i >> 7, c = i & 127;
        const int gr = r;
        bf16 val = (gr < seq_len) ? k[kvbase + (long long)gr * HEAD_DIM + c] : __float2bfloat16(0.f);
        const int sw = (c >> 3) ^ (r & 7);
        sK[r][sw * 8 + (c & 7)] = val;
    }
    __syncthreads();
    uint32_t qa[8][4];
    {
        uint32_t t[4];
#pragma unroll
        for (int ks = 0; ks < 8; ++ks) {
            ldmatrix_x4(t, sQ, wrow, ks * 16);
            qa[ks][0] = t[0]; qa[ks][1] = t[2]; qa[ks][2] = t[1]; qa[ks][3] = t[3];
        }
    }
    const int cbase0 = 2 * (lane % 4);
    const int mrow0 = wrow + lane / 4;
    const int mrow1 = mrow0 + 8;
    for (int ns = 0; ns < 4; ++ns) {
        float sacc[4] = {0.f, 0.f, 0.f, 0.f};
#pragma unroll
        for (int ks = 0; ks < 8; ++ks) {
            uint32_t kf[2];
            ldmatrix_x2_k(kf, sK, ns * 8, ks * 16);
            mma_m16n8k16_bf16(sacc, qa[ks], kf, sacc);
        }
        const int gcol0 = ns * 8 + cbase0;
        // dump as row-major S[mrow][gcol] with padding per warp region
        float* o0 = S_out + (long long)mrow0 * seq_len;
        float* o1 = S_out + (long long)mrow1 * seq_len;
        o0[gcol0]     = sacc[0] * scale;
        o0[gcol0 + 1] = sacc[1] * scale;
        o1[gcol0]     = sacc[2] * scale;
        o1[gcol0 + 1] = sacc[3] * scale;
    }
}

